('anac', 'a86cd271-84b8-4ba3-9b47-33a601f1cc20', 'Conhecimentos Técnicos', null, 'OS VENTOS PRÉ-FRONTAIS DE UMA FRENTE QUENTE, NO HEMISFÉRIO SUL, PODEM FLUIR DE:', null, '[{"letra": "A", "texto": "n", "imagem_url": null}, {"letra": "B", "texto": "e", "imagem_url": null}, {"letra": "C", "texto": "sw", "imagem_url": null}, {"letra": "D", "texto": "ne", "imagem_url": null}]'::jsonb, 'C', null),
