-- Cabin Crew · corrige a ordem das alternativas em questões cujas opções são só letras (A, B, C, D)
-- Ex.: Matrizes de Raven, em que a figura mostra os rótulos A–D. Essas não podem ser embaralhadas.
-- Pode rodar mais de uma vez.

on conflict (banco, origem_id) do update set alternativas = excluded.alternativas, correta = excluded.correta, categoria = excluded.categoria;

select banco, count(*) as corrigidas from questoes where origem_id in ('1b04213a-dbb1-4881-acab-e1baf3d7de88','36680d14-f8a5-4e7f-8fbb-38c693fe966e','3e36b4c0-2bc0-414c-a10b-aa1852eada43','6e0ea647-b046-4205-bc61-73d62d774e60','838e17d5-81a7-4854-896b-fe6a3268a4ba','8bf028c3-6d4f-4c1b-8bfc-4ece064d2517','9e157a89-3a23-479c-a311-f9fa06fdf1f4','9e1d3403-ffc9-45fa-8e88-f030846d55cc','9f60dc60-12c8-4574-b29c-973cfd9dc101','a86cd271-84b8-4ba3-9b47-33a601f1cc20','af5f85ab-8b4e-428c-87b1-8cf44ea867bc','e3baedd2-bb3a-4fe6-8325-68fbb03937ab','b71e7775-d0a5-494d-929c-1a2ef0ea5a97','613a8b5e-8687-4f86-b692-efc295bcf957','209ec8bd-211c-4480-8feb-a1bfea988870','cca96c12-0363-4e33-ac66-a2b513d39f96','2ad73607-1b9b-43fd-99b6-b09cbc818588','aec8d59e-ee8c-480e-8cd8-ce35a0026ee8','63c8e597-bf3e-4b2f-bad1-b047f3639084','792975fa-c3fd-4244-9774-f7d92b245f88','d43d642c-7019-4bb6-b66c-c49e733dba89','fd81b91b-99c5-4028-9534-5a990af05b33','b900624a-8507-4be3-84b1-9f414b93fed5','fb68606c-4189-439c-aac1-ecbc4347d80a','37d1ceea-0fae-425b-beb8-e0a73541b114','1915110e-e40d-44cd-8210-d194c30402ab','4be0a4f4-3624-45c8-85ba-9a42499bf750','c1caf451-a0c6-4e94-8531-cda34b50a436','474bfd51-f500-4f19-8f82-88320af2fcde','9d3c4bfa-fe4a-4795-a579-143158ece60d','48be8d7e-8610-45f8-8885-506aad8e5083','01c2b212-5edc-4fb3-b293-db26abf1e3c2','9cf843d3-db86-488e-8055-7932bbe11279') group by banco;
